<template>
  <div class="workspace-page">
    <WorkspaceHeading title="外部回调" :loading="loading" :busy="busy" @refresh="load()" />
    <ResourceList title="回调配置列表" icon="Connection" :items="configs" :loading="loading" :busy="busy" :error="error" :search-keys="['name','description','registry.name']" :sorts="[{key:'name',label:'名称'},{key:'created_at',label:'创建时间'}]" :filter-options="[{value:'true',label:'启用'},{value:'false',label:'停用'}]" filter-key="enabled" empty-text="暂无外部回调配置" @refresh="load()" @selection-change="selected=$event">
      <template #actions><el-button type="danger" :disabled="!selected.length || busy || loading" @click="deleteTargets=selected;deleteVisible=true">删除</el-button><el-button type="primary" :disabled="loading || busy" @click="edit()">添加回调</el-button></template>
      <template #feedback><div v-if="actionError" class="management-error" role="alert"><span>{{actionError}}</span><el-button link @click="actionError=''">关闭</el-button></div></template>
      <el-table-column type="selection" width="48" :selectable="()=>!busy && !loading" /><el-table-column prop="name" label="名称" min-width="170" show-overflow-tooltip /><el-table-column label="状态" width="100"><template #default="{row}"><el-switch :model-value="row.enabled" :disabled="busy || loading" :aria-label="`${row.enabled?'停用':'启用'}回调 ${row.name}`" @change="toggle(row)" /></template></el-table-column><el-table-column label="来源仓库" min-width="160"><template #default="{row}">{{row.registry?.name || '—'}}</template></el-table-column><el-table-column prop="description" label="说明" min-width="200" show-overflow-tooltip /><el-table-column prop="trigger_count" label="触发次数" width="100" /><el-table-column label="最近触发" width="180"><template #default="{row}">{{formatDate(row.last_triggered_at)}}</template></el-table-column><el-table-column label="操作" min-width="250"><template #default="{row}"><div class="management-row-actions"><el-button link :disabled="busy" @click="showUrl(row)">接入配置</el-button><el-button link :disabled="busy" @click="viewLogs(row)">日志</el-button><el-button link type="primary" :disabled="busy" @click="edit(row)">编辑</el-button><el-button link type="danger" :disabled="busy" @click="deleteTargets=[row];deleteVisible=true">删除</el-button></div></template></el-table-column>
      <template #count><span v-if="selected.length">已选 {{selected.length}} 项</span></template>
    </ResourceList>
    <FormDialog v-model="visible" :title="form.id?'编辑回调':'添加回调'" :loading="saving" @confirm="save" @cancel="visible=false">
      <div v-if="formError" class="management-error management-feedback" role="alert">{{formError}}</div><el-form ref="formRef" :model="form" :rules="rules" label-position="top" :disabled="saving" @submit.prevent="save"><el-form-item label="名称" prop="name"><el-input v-model="form.name" placeholder="输入回调用途" maxlength="100" /></el-form-item><el-form-item label="说明"><el-input v-model="form.description" type="textarea" :rows="2" placeholder="填写回调说明（可选）" /></el-form-item><el-form-item label="来源仓库" prop="registry_id"><el-select v-model="form.registry_id" placeholder="选择发送镜像事件的仓库" :loading="optionsLoading"><el-option v-for="registry in registries" :key="registry.id" :label="registry.name" :value="registry.id" /></el-select><p class="management-form-help">仓库选项加载失败时，可关闭后重试。</p></el-form-item><el-form-item label="签名密钥" prop="secret"><el-input v-model="form.secret" type="password" show-password autocomplete="new-password" placeholder="启用回调时必须设置签名密钥" maxlength="200" /><p class="management-form-help">服务端只接受具有有效签名的请求。请在来源仓库配置相同密钥。</p></el-form-item><el-form-item label="回调状态"><el-switch v-model="form.enabled" active-text="启用" inactive-text="停用" aria-label="回调状态" /></el-form-item><button type="submit" hidden>保存回调</button></el-form>
    </FormDialog>
    <FormDialog v-model="urlVisible" title="回调接入配置" wide :show-footer="false">
      <p class="management-description">在外部镜像仓库中配置以下回调地址，并使用对应签名密钥。镜像提交后的发布行为由应用环境授权控制。</p><div class="webhook-config-section"><h3>回调地址</h3><el-input :model-value="webhookUrl" readonly aria-label="回调地址"><template #append><el-button @click="copyValue(webhookUrl,'回调地址')">复制</el-button></template></el-input></div><div class="webhook-config-section"><h3>自建镜像仓库配置</h3><p class="management-form-help">将以下内容加入仓库配置文件 config.yml。预览中的密钥已隐藏，复制完整配置时会包含实际密钥。</p><pre class="management-code">{{configText(false)}}</pre><el-button style="margin-top:12px" @click="copyValue(configText(true),'接入配置')">复制完整配置</el-button></div><div v-if="current?.secret" class="webhook-config-section"><h3>签名密钥</h3><el-input :model-value="current.secret" type="password" show-password readonly aria-label="回调签名密钥" /><p class="management-form-help">仅在需要接入时查看，勿将包含密钥的配置分享给他人。</p></div><el-collapse class="webhook-config-section"><el-collapse-item title="接入说明" name="help"><p class="management-description">在仓库的回调设置中添加镜像推送事件，将接收地址设为上述地址，并按仓库支持的方式配置签名。自建仓库修改配置后需要重新加载服务。可通过推送测试镜像并查看本页日志确认结果。</p></el-collapse-item></el-collapse><template #footer><el-button @click="urlVisible=false">关闭</el-button><el-button type="primary" @click="copyValue(webhookUrl,'回调地址')">复制地址</el-button></template>
    </FormDialog>
    <FormDialog v-model="logsVisible" :title="`${current?.name || '回调'} · 执行日志`" extra-wide :show-footer="false"><div v-if="logsError" class="management-error management-feedback" role="alert">{{logsError}}</div><el-table v-loading="logsLoading" :data="logs" empty-text="暂无执行日志" max-height="440"><el-table-column label="状态" width="130"><template #default="{row}"><StatusBadge :value="row.status" /></template></el-table-column><el-table-column label="镜像引用" min-width="200"><template #default="{row}"><code>{{row.image_name}}:{{row.image_tag}}</code></template></el-table-column><el-table-column prop="message" label="执行信息" min-width="230" show-overflow-tooltip /><el-table-column label="耗时" width="100"><template #default="{row}">{{row.execution_time}} 秒</template></el-table-column><el-table-column label="触发时间" width="180"><template #default="{row}">{{formatDate(row.created_at)}}</template></el-table-column></el-table><template #footer><el-button @click="logsVisible=false">关闭</el-button><el-button :loading="logsLoading" @click="refreshLogs">刷新日志</el-button></template></FormDialog>
    <ManagementDeleteDialog v-model="deleteVisible" :items="deleteTargets" kind="回调配置" endpoint="/webhook-configs" warning="将停止接收对应事件，并删除关联回调日志。" @removed="onRemoved" />
  </div>
</template>
<script setup lang="ts">
import { computed,onBeforeUnmount,ref } from 'vue'
import { ElMessage,type FormInstance,type FormRules } from 'element-plus'
import { useClipboard } from '@vueuse/core'
import { api,errorText } from '@/api/workspace'
import { useResource } from '@/composables/useResource'
import { formatDate } from '@/utils/management'
import WorkspaceHeading from '@/components/WorkspaceHeading.vue'
import ResourceList from '@/components/ResourceList.vue'
import FormDialog from '@/components/FormDialog.vue'
import ManagementDeleteDialog from '@/components/ManagementDeleteDialog.vue'
import StatusBadge from '@/components/StatusBadge.vue'
const {data:configs,loading,error,load}=useResource<any[]>('/webhook-configs',[])
const selected=ref<any[]>([]),deleteTargets=ref<any[]>([]),deleteVisible=ref(false),visible=ref(false),urlVisible=ref(false),logsVisible=ref(false),saving=ref(false),toggling=ref(false),actionError=ref(''),formError=ref(''),formRef=ref<FormInstance>(),registries=ref<any[]>([]),optionsLoading=ref(false),current=ref<any>(),webhookUrl=ref(''),logs=ref<any[]>([]),logsError=ref(''),logsLoading=ref(false)
const form=ref<any>({name:'',description:'',enabled:true,registry_id:undefined,secret:''}),busy=computed(()=>saving.value || toggling.value || deleteVisible.value)
const {copy}=useClipboard({legacy:true});let disposed=false,logsSequence=0
const rules:FormRules={name:[{required:true,whitespace:true,message:'请输入回调名称',trigger:'blur'}],registry_id:[{required:true,message:'请选择来源仓库',trigger:'change'}],secret:[{validator:(_r,value,done)=>done(form.value.enabled && !value?new Error('启用回调需要设置签名密钥'):undefined),trigger:['blur','change']}]}
async function edit(row?:any){form.value=row?{id:row.id,name:row.name,description:row.description || '',enabled:row.enabled,registry_id:row.registry_id,secret:row.secret || ''}:{name:'',description:'',enabled:true,registry_id:undefined,secret:''};formError.value='';formRef.value?.clearValidate();visible.value=true;optionsLoading.value=true;try{const result=await api<any[]>('GET','/registries');if(!disposed)registries.value=result || []}catch(cause){if(!disposed)formError.value=`仓库选项加载失败：${errorText(cause)}`}finally{if(!disposed)optionsLoading.value=false}}
function payload(row:any){return {name:row.name.trim(),description:row.description || '',enabled:row.enabled,registry_id:row.registry_id,secret:row.secret || ''}}
async function save(){if(saving.value || optionsLoading.value || !await formRef.value?.validate().catch(()=>false) || saving.value)return;saving.value=true;formError.value='';try{await api(form.value.id?'PUT':'POST',form.value.id?`/webhook-configs/${form.value.id}`:'/webhook-configs',payload(form.value));visible.value=false;ElMessage.success('回调配置已保存');await load()}catch(cause){formError.value=errorText(cause)}finally{saving.value=false}}
async function toggle(row:any){if(busy.value)return;toggling.value=true;actionError.value='';try{await api('PUT',`/webhook-configs/${row.id}`,payload({...row,enabled:!row.enabled}));ElMessage.success(row.enabled?'回调已停用':'回调已启用');await load()}catch(cause){actionError.value=errorText(cause)}finally{toggling.value=false}}
async function showUrl(row:any){current.value=row;urlVisible.value=true;webhookUrl.value='';try{const result=await api('GET',`/webhook-configs/${row.id}/url`);if(!disposed && current.value?.id===row.id)webhookUrl.value=result.url}catch(cause){urlVisible.value=false;actionError.value=errorText(cause)}}
function configText(includeSecret:boolean){return `notifications:\n  endpoints:\n    - name: dockerun\n      disabled: false\n      url: ${webhookUrl.value}\n      timeout: 5s\n      threshold: 5\n      backoff: 1s${current.value?.secret?`\n      headers:\n        X-Registry-Signature: [${JSON.stringify(includeSecret?current.value.secret:'******')}]`:''}`}
async function copyValue(value:string,label:string){if(!value)return;try{await copy(value);ElMessage.success(`${label}已复制`)}catch{ElMessage.error('复制失败，请重试')}}
function viewLogs(row:any){current.value=row;logs.value=[];logsVisible.value=true;void refreshLogs()}
async function refreshLogs(){if(!current.value)return;const sequence=++logsSequence,id=current.value.id;logsLoading.value=true;logsError.value='';try{const result=await api<any[]>('GET',`/webhook-logs?config_id=${id}`);if(!disposed && sequence===logsSequence)logs.value=result || []}catch(cause){if(!disposed && sequence===logsSequence)logsError.value=errorText(cause)}finally{if(!disposed && sequence===logsSequence)logsLoading.value=false}}
function onRemoved(ids:number[]){configs.value=configs.value.filter(row=>!ids.includes(row.id));selected.value=[]}
onBeforeUnmount(()=>{disposed=true;logsSequence++})
</script>
<style scoped>
.webhook-config-section { margin-top:22px; }.webhook-config-section h3 { margin:0 0 10px; font-size:14px; font-weight:500; }.webhook-config-section .management-code { margin-top:12px; }
</style>
